message.content:
{
  "description": "The creature is a quadrupedal animal with the overall body, dense brown fur, head, and limbs of a brown bear shown in right-facing profile, but its back, neck, shoulders, and portions of its legs are covered by a glossy, dark brown to nearly black segmented exoskeleton resembling a beetle. A lighter tan segmented plating covers the throat, chest, and belly. A single long, glossy black, sickle-shaped horn with small tooth-like spines along its inner curve projects upward and backward from the center of the forehead. The animal stands on four thick furry legs with clawed paws on a plain light background, with a small furry tail visible at the rear beneath the dorsal plates.",
  "parts": [
    {
      "part": "head",
      "looks_like": "a brown bear head with dense brown fur, a lighter tan muzzle, a large black nose at the tip, small dark brown eyes on the side, and a closed mouth with a faint smile line",
      "where": "at the front of the body, facing to the right"
    },
    {
      "part": "horns",
      "looks_like": "a single long, glossy black, strongly curved horn that is smooth and shiny with several small pointed projections along the inner concave edge, tapering to a sharp tip",
      "where": "emerging from the center of the forehead on top of the head between the ears, curving up and back over the head"
    },
    {
      "part": "ears",
      "looks_like": "two small, rounded, upright ears covered in fluffy brown fur with slightly darker edges",
      "where": "on top of the head, one on each side of the base of the horn"
    },
    {
      "part": "legs",
      "looks_like": "four thick, muscular legs covered in long brown fur, with large glossy dark brown to black plates on the shoulders, upper hind thighs, and lower fore and hind shins; the plates on the lower foreleg have pointed spiky edges",
      "where": "two front legs under the chest and two hind legs under the rear, supporting the body"
    },
    {
      "part": "feet",
      "looks_like": "four broad, flat paws with brown fur on top and long, curved, dark claws protruding from the toes",
      "where": "at the bottom of each leg in contact with the ground"
    },
    {
      "part": "tail",
      "looks_like": "a small, short, fluffy brown tail with shaggy fur",
      "where": "at the extreme rear of the body, protruding from beneath the dorsal plates on the left side of the image"
    },
    {
      "part": "plates",
      "looks_like": "glossy dark brown to black overlapping segmented plates with a hard, shiny, beetle-like surface and small circular breathing holes along the lower side segments; additional large smooth shoulder plates and segmented shin plates, and a contrasting light tan segmented plating with oval holes on the neck and belly",
      "where": "covering the dorsal back from the base of the neck to the rump, over the shoulders, on the upper hind thighs, on the lower front and hind legs, and as a lighter band around the throat, chest, and underside"
    },
    {
      "part": "shell",
      "looks_like": "a hard, glossy, dark domed carapace made of fused overlapping segments that is highly reflective",
      "where": "forming the main dorsal covering over the back and the large shoulder caps"
    }
  ],
  "attached_objects": [],
  "animals": [
    "bear",
    "rhinoceros beetle"
  ],
  "separate_bodies": 1,
  "heads": 1,
  "walking_legs": 4,
  "wings": 0,
  "extra_limb_pieces": 0,
  "tails": 1
}
